import subprocess, sys
EXE="/workspace/dataset/test8_executable"
def run(arg):
    p=subprocess.run([EXE,"--a="+arg],capture_output=True)
    return p.returncode,p.stdout.decode('utf-8','replace'),p.stderr.decode('utf-8','replace')
def esc(s):
    return s.replace('\\','\\\\').replace('\n','\\n').replace('\t','\\t').replace('\r','\\r')
def show(arg,label=None):
    rc,o,e=run(arg)
    el=e.strip().splitlines()
    etail = el[-1] if el else ''
    print("IN=[%s] RC=%d OUT=[%s]%s"%(esc(label if label is not None else arg),rc,esc(o), ("" if rc==0 else " ERRLAST=["+esc(etail)+"]")))
if __name__=="__main__":
    for line in sys.stdin.read().split('\n'):
        if line=='': continue
        arg=line.encode().decode('unicode_escape') if '\\' in line else line
        show(arg,line)
